-- Exact qualified retention provenance/audit and company hard-delete defense.
-- Apply after full source-owned additive class/qualified-transition foundation.
-- Three existing trigger bodies, plus the omitted immutable provenance table
-- and internal source-owned helper. No purge/delete/business calls or backfill.
-- Preserve ALL current target identities, stronger lifecycle helpers and ACLs.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
DO $retention_audit_harddelete$
DECLARE config constant jsonb := '[{"signature":"gridex_correction_process.capture_v1()","before":"ef20fd588333aca906dea9b6c2064210","after":"68fe8b6945faaf2d8b441bfea7cf2cbe","original":"\nDECLARE\n old_row jsonb; new_row jsonb; old_fact jsonb; new_fact jsonb;\n old_company text; new_company text; selected_company uuid; fact_id bigint;\n fields text[]:=ARRAY[\n  ''id'',''company_id'',''customer_id'',''customer_contract_id'',''contract_id'',''site_id'',''customer_site_id'',\n  ''metering_point_id'',''meter_point_id'',''normalized_metering_point_id'',''facility_id'',\n  ''normalized_facility_id'',''site_facility_id'',''ediel_metering_point_id'',''ediel_reference'',\n  ''grid_owner_id'',''grid_owner_ediel_id'',''switch_request_id'',''supplier_switch_request_id'',\n  ''customer_case_id'',''customer_operation_job_id'',''operation_id'',''outbound_request_id'',\n  ''cancellation_ediel_message_id'',''source_message_id'',''source_switch_request_id'',\n  ''outbound_z03_message_id'',''inbound_z04_message_id'',''rff_li_reference'',\n  ''event_type'',''event_status'',''event_code'',''case_type'',''job_type'',''task_type'',\n  ''request_type'',''process_type'',''source_process'',''source'',''status'',''start_status'',\n  ''cancellation_status'',''withdrawal_scenario'',''withdrawal_possible'',''switch_can_be_stopped'',\n  ''cancellation_required'',''billing_blocked'',''billing_manual_review'',''lifecycle_blocked'',\n  ''start_date'',''end_date'',''actual_start_date'',''actual_end_date'',''starts_at'',''ends_at'',\n  ''ended_at'',''signed_at'',''termination_notice_date'',''withdrawal_requested_at'',\n  ''requested_start_date'',''confirmed_start_date'',''completed_at'',''failed_at'',\n  ''submitted_at'',''resolved_at'',''closed_at'',''move_in_date'',''move_out_date'',\n  ''happened_at'',''occurred_at'',''created_at'',''updated_at'',''archived_at'',''source_type'',''operation_id'',\n  ''idempotency_key'',''actual_start_at'',''delivery_start_at'',''withdrawal_deadline_at''\n ];\nBEGIN\n IF TG_TABLE_SCHEMA<>''public'' OR NOT EXISTS\n  (SELECT FROM gridex_correction_process.epochs e WHERE e.table_name=TG_TABLE_NAME) THEN\n  RAISE EXCEPTION ''correction_process_unregistered_producer'' USING ERRCODE=''23514'';\n END IF;\n IF TG_OP<>''INSERT'' THEN old_row:=to_jsonb(OLD); END IF;\n IF TG_OP<>''DELETE'' THEN new_row:=to_jsonb(NEW); END IF;\n IF coalesce(octet_length(old_row::text),0)+coalesce(octet_length(new_row::text),0)>6291456 THEN\n  RAISE EXCEPTION ''correction_process_transition_too_large'' USING ERRCODE=''22001'';\n END IF;\n SELECT jsonb_object_agg(key,value) INTO old_fact FROM jsonb_each(old_row) WHERE key=ANY(fields);\n SELECT jsonb_object_agg(key,value) INTO new_fact FROM jsonb_each(new_row) WHERE key=ANY(fields);\n IF coalesce(octet_length(old_fact::text),0)>65536 OR coalesce(octet_length(new_fact::text),0)>65536 THEN\n  RAISE EXCEPTION ''correction_process_fact_too_large'' USING ERRCODE=''22001'';\n END IF;\n old_company:=old_row->>''company_id''; new_company:=new_row->>''company_id'';\n selected_company:=coalesce(old_company,new_company)::uuid;\n INSERT INTO gridex_correction_process.facts(table_name,row_id,operation,company_id,old_fact,new_fact,facts_hash)\n VALUES (TG_TABLE_NAME,(coalesce(old_row,new_row)->>''id'')::uuid,TG_OP,selected_company,old_fact,new_fact,\n  encode(sha256(convert_to(jsonb_build_object(''table'',TG_TABLE_NAME,''rowId'',coalesce(old_row,new_row)->>''id'',\n   ''operation'',TG_OP,''old'',old_fact,''new'',new_fact)::text,''UTF8'')),''hex'')) RETURNING id INTO fact_id;\n IF selected_company IS NULL OR (TG_OP=''UPDATE'' AND old_company IS DISTINCT FROM new_company) THEN\n  INSERT INTO gridex_correction_process.gaps(fact_id,reason,old_scope,new_scope)\n  VALUES(fact_id,CASE WHEN old_company IS NULL OR new_company IS NULL THEN ''unbound_company'' ELSE ''company_changed'' END,\n   old_fact,new_fact);\n END IF;\n IF TG_OP=''DELETE'' THEN RETURN OLD; END IF;\n RETURN NEW;\nEND ","patched":"\nDECLARE\n old_row jsonb; new_row jsonb; old_fact jsonb; new_fact jsonb;\n old_company text; new_company text; selected_company uuid; fact_id bigint;\n fields text[]:=ARRAY[\n  ''id'',''company_id'',''customer_id'',''customer_contract_id'',''contract_id'',''site_id'',''customer_site_id'',\n  ''metering_point_id'',''meter_point_id'',''normalized_metering_point_id'',''facility_id'',\n  ''normalized_facility_id'',''site_facility_id'',''ediel_metering_point_id'',''ediel_reference'',\n  ''grid_owner_id'',''grid_owner_ediel_id'',''switch_request_id'',''supplier_switch_request_id'',\n  ''customer_case_id'',''customer_operation_job_id'',''operation_id'',''outbound_request_id'',\n  ''cancellation_ediel_message_id'',''source_message_id'',''source_switch_request_id'',\n  ''outbound_z03_message_id'',''inbound_z04_message_id'',''rff_li_reference'',\n  ''event_type'',''event_status'',''event_code'',''case_type'',''job_type'',''task_type'',\n  ''request_type'',''process_type'',''source_process'',''source'',''status'',''start_status'',\n  ''cancellation_status'',''withdrawal_scenario'',''withdrawal_possible'',''switch_can_be_stopped'',\n  ''cancellation_required'',''billing_blocked'',''billing_manual_review'',''lifecycle_blocked'',\n  ''start_date'',''end_date'',''actual_start_date'',''actual_end_date'',''starts_at'',''ends_at'',\n  ''ended_at'',''signed_at'',''termination_notice_date'',''withdrawal_requested_at'',\n  ''requested_start_date'',''confirmed_start_date'',''completed_at'',''failed_at'',\n  ''submitted_at'',''resolved_at'',''closed_at'',''move_in_date'',''move_out_date'',\n  ''happened_at'',''occurred_at'',''created_at'',''updated_at'',''archived_at'',''source_type'',''operation_id'',\n  ''idempotency_key'',''actual_start_at'',''delivery_start_at'',''withdrawal_deadline_at''\n ];\nBEGIN IF TG_OP=''UPDATE'' AND public.ediel_capture_customer_record_retention_origin_v1(TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW;END IF;\n IF TG_TABLE_SCHEMA<>''public'' OR NOT EXISTS\n  (SELECT FROM gridex_correction_process.epochs e WHERE e.table_name=TG_TABLE_NAME) THEN\n  RAISE EXCEPTION ''correction_process_unregistered_producer'' USING ERRCODE=''23514'';\n END IF;\n IF TG_OP<>''INSERT'' THEN old_row:=to_jsonb(OLD); END IF;\n IF TG_OP<>''DELETE'' THEN new_row:=to_jsonb(NEW); END IF;\n IF coalesce(octet_length(old_row::text),0)+coalesce(octet_length(new_row::text),0)>6291456 THEN\n  RAISE EXCEPTION ''correction_process_transition_too_large'' USING ERRCODE=''22001'';\n END IF;\n SELECT jsonb_object_agg(key,value) INTO old_fact FROM jsonb_each(old_row) WHERE key=ANY(fields);\n SELECT jsonb_object_agg(key,value) INTO new_fact FROM jsonb_each(new_row) WHERE key=ANY(fields);\n IF coalesce(octet_length(old_fact::text),0)>65536 OR coalesce(octet_length(new_fact::text),0)>65536 THEN\n  RAISE EXCEPTION ''correction_process_fact_too_large'' USING ERRCODE=''22001'';\n END IF;\n old_company:=old_row->>''company_id''; new_company:=new_row->>''company_id'';\n selected_company:=coalesce(old_company,new_company)::uuid;\n INSERT INTO gridex_correction_process.facts(table_name,row_id,operation,company_id,old_fact,new_fact,facts_hash)\n VALUES (TG_TABLE_NAME,(coalesce(old_row,new_row)->>''id'')::uuid,TG_OP,selected_company,old_fact,new_fact,\n  encode(sha256(convert_to(jsonb_build_object(''table'',TG_TABLE_NAME,''rowId'',coalesce(old_row,new_row)->>''id'',\n   ''operation'',TG_OP,''old'',old_fact,''new'',new_fact)::text,''UTF8'')),''hex'')) RETURNING id INTO fact_id;\n IF selected_company IS NULL OR (TG_OP=''UPDATE'' AND old_company IS DISTINCT FROM new_company) THEN\n  INSERT INTO gridex_correction_process.gaps(fact_id,reason,old_scope,new_scope)\n  VALUES(fact_id,CASE WHEN old_company IS NULL OR new_company IS NULL THEN ''unbound_company'' ELSE ''company_changed'' END,\n   old_fact,new_fact);\n END IF;\n IF TG_OP=''DELETE'' THEN RETURN OLD; END IF;\n RETURN NEW;\nEND ","source_line":7172,"source_statement_sha256":"b0d19633ecce8ae5512b555b6a1b4f26817d288705eb2feef520b261c9ddba40","expected":{"owner":"postgres","acl":"{postgres=X/postgres}","proconfig":["search_path=pg_catalog"],"provolatile":"v","prosecdef":true,"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":0,"proargnames":null,"proargmodes":null,"return_type":"trigger","proretset":false,"identity_arguments":"","arguments":"","language":"plpgsql"}},{"signature":"public.gridex_audit_portfolio_settlement_write()","before":"12054f3bc27579c99ba847d0f33a0fc9","after":"ff6f4bfdeeaa7b68c9e5e99a81f188d9","original":"\nbegin\n  insert into public.portfolio_settlement_audit_log(\n    company_id,portfolio_id,settlement_id,actor_user_id,permission,action,\n    old_values,new_values,reason,calculation_snapshot_sha256,approval\n  ) values(\n    case when tg_op=''INSERT'' then new.company_id else old.company_id end,\n    case when tg_op=''INSERT'' then new.portfolio_id else old.portfolio_id end,\n    case when tg_op=''INSERT'' then new.id else old.id end,\n    case\n      when tg_op=''INSERT'' then new.created_by\n      when new.locked_by is distinct from old.locked_by then new.locked_by\n      when new.approved_by is distinct from old.approved_by then new.approved_by\n      when new.reviewed_by is distinct from old.reviewed_by then new.reviewed_by\n      when new.calculated_by is distinct from old.calculated_by then new.calculated_by\n      else coalesce(\n        nullif(current_setting(''gridex.portfolio_actor_user_id'',true), '''')::uuid,\n        new.created_by\n      )\n    end,\n    case\n      when tg_op=''INSERT'' then case when new.source=''import'' then ''portfolio_settlement.import'' else ''portfolio_settlement.create'' end\n      when new.is_current=false and old.is_current then ''portfolio_settlement.correct''\n      when new.status=''calculated'' and old.status is distinct from new.status then ''portfolio_settlement.calculate''\n      when new.status=''reviewed'' and old.status is distinct from new.status then ''portfolio_settlement.review''\n      when new.status=''final'' and old.status is distinct from new.status then ''portfolio_settlement.approve''\n      when new.status=''locked'' and old.status is distinct from new.status then ''portfolio_settlement.lock''\n      else ''portfolio_settlement.correct''\n    end,\n    case\n      when tg_op=''INSERT'' then ''settlement.created''\n      when new.is_current=false and old.is_current then ''settlement.superseded''\n      when new.status is distinct from old.status then ''settlement.''||new.status\n      else ''settlement.updated''\n    end,\n    case when tg_op=''INSERT'' then null else to_jsonb(old) end,\n    case when tg_op=''DELETE'' then null else to_jsonb(new) end,\n    coalesce(\n      nullif(current_setting(''gridex.portfolio_audit_reason'',true),''''),\n      case when tg_op=''INSERT'' then new.correction_reason else coalesce(new.correction_reason,old.correction_reason) end\n    ),\n    new.calculation_snapshot_sha256,\n    case\n      when new.approved_by is not null then jsonb_build_object(''approved_by'',new.approved_by,''approved_at'',new.approved_at)\n      else null\n    end\n  );\n  return new;\nend ","patched":"\nBEGIN IF TG_OP=''UPDATE'' AND public.ediel_is_qualified_finance_retention_transition_v1(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW;END IF;\n  insert into public.portfolio_settlement_audit_log(\n    company_id,portfolio_id,settlement_id,actor_user_id,permission,action,\n    old_values,new_values,reason,calculation_snapshot_sha256,approval\n  ) values(\n    case when tg_op=''INSERT'' then new.company_id else old.company_id end,\n    case when tg_op=''INSERT'' then new.portfolio_id else old.portfolio_id end,\n    case when tg_op=''INSERT'' then new.id else old.id end,\n    case\n      when tg_op=''INSERT'' then new.created_by\n      when new.locked_by is distinct from old.locked_by then new.locked_by\n      when new.approved_by is distinct from old.approved_by then new.approved_by\n      when new.reviewed_by is distinct from old.reviewed_by then new.reviewed_by\n      when new.calculated_by is distinct from old.calculated_by then new.calculated_by\n      else coalesce(\n        nullif(current_setting(''gridex.portfolio_actor_user_id'',true), '''')::uuid,\n        new.created_by\n      )\n    end,\n    case\n      when tg_op=''INSERT'' then case when new.source=''import'' then ''portfolio_settlement.import'' else ''portfolio_settlement.create'' end\n      when new.is_current=false and old.is_current then ''portfolio_settlement.correct''\n      when new.status=''calculated'' and old.status is distinct from new.status then ''portfolio_settlement.calculate''\n      when new.status=''reviewed'' and old.status is distinct from new.status then ''portfolio_settlement.review''\n      when new.status=''final'' and old.status is distinct from new.status then ''portfolio_settlement.approve''\n      when new.status=''locked'' and old.status is distinct from new.status then ''portfolio_settlement.lock''\n      else ''portfolio_settlement.correct''\n    end,\n    case\n      when tg_op=''INSERT'' then ''settlement.created''\n      when new.is_current=false and old.is_current then ''settlement.superseded''\n      when new.status is distinct from old.status then ''settlement.''||new.status\n      else ''settlement.updated''\n    end,\n    case when tg_op=''INSERT'' then null else to_jsonb(old) end,\n    case when tg_op=''DELETE'' then null else to_jsonb(new) end,\n    coalesce(\n      nullif(current_setting(''gridex.portfolio_audit_reason'',true),''''),\n      case when tg_op=''INSERT'' then new.correction_reason else coalesce(new.correction_reason,old.correction_reason) end\n    ),\n    new.calculation_snapshot_sha256,\n    case\n      when new.approved_by is not null then jsonb_build_object(''approved_by'',new.approved_by,''approved_at'',new.approved_at)\n      else null\n    end\n  );\n  return new;\nend ","source_line":54555,"source_statement_sha256":"098cb0c4a76c1337d0aa83d8e722651c365c907f462aa456076b60d2c825aa81","expected":{"owner":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres}","proconfig":["search_path=public, pg_temp"],"provolatile":"v","prosecdef":true,"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":0,"proargnames":null,"proargmodes":null,"return_type":"trigger","proretset":false,"identity_arguments":"","arguments":"","language":"plpgsql"}},{"signature":"public.gridex_guard_company_hard_delete_v1()","before":"b760388550527115f5c5048b2f7478b1","after":"5fa9ea090a1f965c5b56bfc2b9d5fae9","original":"\ndeclare\n  v_retained text[];\nbegin\n  if current_user in (''postgres'', ''supabase_admin'') then\n    return old;\n  end if;\n  if old.status = ''deleted_test_only'' then\n    v_retained := public.gridex_company_retained_history_v1(old.id);\n    if cardinality(v_retained) = 0 then\n      return old;\n    end if;\n    raise exception using\n      errcode = ''23001'',\n      message = ''company_hard_delete_blocked'',\n      detail = ''Disposable tenant still holds retained history: '' || array_to_string(v_retained, '','');\n  end if;\n  raise exception using\n    errcode = ''23001'',\n    message = ''company_hard_delete_blocked'',\n    detail = ''Retained audit, journal and billing history would be cascaded away; close the tenant through canonical_transition_tenant_lifecycle.'';\nend\n","patched":"\ndeclare\n  v_retained text[];\nbegin\n  if current_user in (''postgres'', ''supabase_admin'') then\n    return old;\n  end if;\n  if old.status = ''deleted_test_only'' then\n    v_retained := public.gridex_company_retained_history_v1(old.id) || array_remove(array[\n      case when exists (select 1 from public.canonical_audit_events x where x.company_id = old.id) then ''canonical_audit_events'' end,\n      case when exists (select 1 from public.canonical_command_results x where x.company_id = old.id) then ''canonical_command_results'' end,\n      case when exists (select 1 from public.canonical_domain_events x where x.company_id = old.id) then ''canonical_domain_events'' end,\n      case when exists (select 1 from public.canonical_event_outbox x where x.company_id = old.id) then ''canonical_event_outbox'' end,\n      case when exists (select 1 from public.pricing_audit_logs x where x.company_id = old.id) then ''pricing_audit_logs'' end,\n      case when exists (select 1 from public.domain_events x where x.company_id = old.id) then ''domain_events'' end,\n      case when exists (select 1 from public.ediel_ack_transaction_results x where x.company_id = old.id) then ''ediel_ack_transaction_results'' end,\n      case when exists (select 1 from public.ediel_business_correlations x where x.company_id = old.id) then ''ediel_business_correlations'' end,\n      case when exists (select 1 from public.ediel_business_errors x where x.company_id = old.id) then ''ediel_business_errors'' end,\n      case when exists (select 1 from public.ediel_route_history x where x.company_id = old.id) then ''ediel_route_history'' end,\n      case when exists (select 1 from public.ediel_certification_evidence x where x.company_id = old.id) then ''ediel_certification_evidence'' end\n    ], null);\n    if cardinality(v_retained) = 0 then\n      return old;\n    end if;\n    raise exception using\n      errcode = ''23001'',\n      message = ''company_hard_delete_blocked'',\n      detail = ''Disposable tenant still holds retained history: '' || array_to_string(v_retained, '','');\n  end if;\n  raise exception using\n    errcode = ''23001'',\n    message = ''company_hard_delete_blocked'',\n    detail = ''Retained audit, journal and billing history would be cascaded away; close the tenant through canonical_transition_tenant_lifecycle.'';\nend\n","source_line":71815,"source_statement_sha256":"6103b6b0ba0c27cc0a4c24ee200a8f13e936b22e4b10b78e5102e880bb88f3f1","expected":{"owner":"postgres","acl":"{postgres=X/postgres}","proconfig":["search_path=public, pg_temp"],"provolatile":"v","prosecdef":false,"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":0,"proargnames":null,"proargmodes":null,"return_type":"trigger","proretset":false,"identity_arguments":"","arguments":"","language":"plpgsql"}}]'::jsonb;
 helper constant jsonb := '{"signature":"public.ediel_capture_customer_record_retention_origin_v1(text,jsonb,jsonb)","definition":"CREATE FUNCTION public.ediel_capture_customer_record_retention_origin_v1(p_table text, p_old jsonb, p_new jsonb) RETURNS boolean\n    LANGUAGE plpgsql SECURITY DEFINER\n    SET search_path TO ''pg_catalog''\n    AS $$DECLARE t gridex_ediel_retention.record_tombstones%rowtype;\n o gridex_ediel_retention.process_retention_origins%rowtype;\nBEGIN\n IF public.ediel_is_qualified_customer_record_transition_v1(p_table,p_old,p_new) IS NOT TRUE THEN RETURN false;END IF;\n SELECT x.* INTO STRICT t FROM gridex_ediel_retention.record_tombstones x\n  JOIN gridex_ediel_retention.record_class_catalog k ON k.retention_class=x.retention_class\n  WHERE k.source_table=p_table AND x.target_id=(p_old->>''id'')::uuid AND x.company_id=(p_old->>''company_id'')::uuid;\n SELECT x.* INTO o FROM gridex_ediel_retention.process_retention_origins x\n  WHERE x.company_id=t.company_id AND x.source_table=p_table AND x.target_id=t.target_id AND x.decision_id=t.decision_id;\n IF FOUND THEN\n  -- The captured full redacted hash is immutable evidence, not a hash of a\n  -- later row whose permitted updated_at may have changed repeatedly. Current\n  -- OLD/NEW state remains protected by the unchanged exact class qualifier.\n  IF o.original_hash IS DISTINCT FROM t.target_hash OR o.redacted_hash!~''^[a-f0-9]{64}$''\n   OR o.journal_retain_until IS DISTINCT FROM t.journal_retain_until\n   OR o.journal_purpose_reference IS DISTINCT FROM t.journal_purpose_reference THEN\n   RAISE EXCEPTION ''record_retention_existing_origin_binding_mismatch'' USING ERRCODE=''23514'';END IF;\n  RETURN true; -- No insertion, replacement, new hash or historical fabrication.\n END IF;\n -- First capture still requires the exact immutable original before erasure.\n -- An already-redacted legacy row with no established origin must fail closed.\n SELECT x.* INTO STRICT t FROM gridex_ediel_retention.record_tombstones x\n  JOIN gridex_ediel_retention.record_class_catalog k ON k.retention_class=x.retention_class\n  WHERE k.source_table=p_table AND x.target_id=(p_old->>''id'')::uuid\n   AND x.target_hash=encode(sha256(convert_to(p_old::text,''UTF8'')),''hex'');\n INSERT INTO gridex_ediel_retention.process_retention_origins(company_id,source_table,target_id,decision_id,original_hash,redacted_hash,journal_retain_until,journal_purpose_reference)\n VALUES(t.company_id,p_table,t.target_id,t.decision_id,t.target_hash,encode(sha256(convert_to(p_new::text,''UTF8'')),''hex''),t.journal_retain_until,t.journal_purpose_reference) ON CONFLICT DO NOTHING;\n SELECT x.* INTO STRICT o FROM gridex_ediel_retention.process_retention_origins x\n  WHERE x.company_id=t.company_id AND x.source_table=p_table AND x.target_id=t.target_id AND x.decision_id=t.decision_id;\n IF o.original_hash IS DISTINCT FROM t.target_hash\n  OR o.redacted_hash IS DISTINCT FROM encode(sha256(convert_to(p_new::text,''UTF8'')),''hex'')\n  OR o.journal_retain_until IS DISTINCT FROM t.journal_retain_until\n  OR o.journal_purpose_reference IS DISTINCT FROM t.journal_purpose_reference THEN\n  RAISE EXCEPTION ''record_retention_first_origin_binding_mismatch'' USING ERRCODE=''23514'';END IF;\n RETURN true;\nEND\n$$;","source_before_body_md5":"c5792bfb611b677f847ea923f42e4947","original":"DECLARE t gridex_ediel_retention.record_tombstones%rowtype;BEGIN\n IF public.ediel_is_qualified_customer_record_transition_v1(p_table,p_old,p_new) IS NOT TRUE THEN RETURN false;END IF;\n SELECT x.* INTO STRICT t FROM gridex_ediel_retention.record_tombstones x JOIN gridex_ediel_retention.record_class_catalog k ON k.retention_class=x.retention_class WHERE k.source_table=p_table AND x.target_id=(p_old->>''id'')::uuid AND x.target_hash=encode(sha256(convert_to(p_old::text,''UTF8'')),''hex'');\n INSERT INTO gridex_ediel_retention.process_retention_origins(company_id,source_table,target_id,decision_id,original_hash,redacted_hash,journal_retain_until,journal_purpose_reference) VALUES(t.company_id,p_table,t.target_id,t.decision_id,t.target_hash,encode(sha256(convert_to(p_new::text,''UTF8'')),''hex''),t.journal_retain_until,t.journal_purpose_reference) ON CONFLICT DO NOTHING;RETURN true;END","patched":"DECLARE t gridex_ediel_retention.record_tombstones%rowtype;\n o gridex_ediel_retention.process_retention_origins%rowtype;\nBEGIN\n IF public.ediel_is_qualified_customer_record_transition_v1(p_table,p_old,p_new) IS NOT TRUE THEN RETURN false;END IF;\n SELECT x.* INTO STRICT t FROM gridex_ediel_retention.record_tombstones x\n  JOIN gridex_ediel_retention.record_class_catalog k ON k.retention_class=x.retention_class\n  WHERE k.source_table=p_table AND x.target_id=(p_old->>''id'')::uuid AND x.company_id=(p_old->>''company_id'')::uuid;\n SELECT x.* INTO o FROM gridex_ediel_retention.process_retention_origins x\n  WHERE x.company_id=t.company_id AND x.source_table=p_table AND x.target_id=t.target_id AND x.decision_id=t.decision_id;\n IF FOUND THEN\n  -- The captured full redacted hash is immutable evidence, not a hash of a\n  -- later row whose permitted updated_at may have changed repeatedly. Current\n  -- OLD/NEW state remains protected by the unchanged exact class qualifier.\n  IF o.original_hash IS DISTINCT FROM t.target_hash OR o.redacted_hash!~''^[a-f0-9]{64}$''\n   OR o.journal_retain_until IS DISTINCT FROM t.journal_retain_until\n   OR o.journal_purpose_reference IS DISTINCT FROM t.journal_purpose_reference THEN\n   RAISE EXCEPTION ''record_retention_existing_origin_binding_mismatch'' USING ERRCODE=''23514'';END IF;\n  RETURN true; -- No insertion, replacement, new hash or historical fabrication.\n END IF;\n -- First capture still requires the exact immutable original before erasure.\n -- An already-redacted legacy row with no established origin must fail closed.\n SELECT x.* INTO STRICT t FROM gridex_ediel_retention.record_tombstones x\n  JOIN gridex_ediel_retention.record_class_catalog k ON k.retention_class=x.retention_class\n  WHERE k.source_table=p_table AND x.target_id=(p_old->>''id'')::uuid\n   AND x.target_hash=encode(sha256(convert_to(p_old::text,''UTF8'')),''hex'');\n INSERT INTO gridex_ediel_retention.process_retention_origins(company_id,source_table,target_id,decision_id,original_hash,redacted_hash,journal_retain_until,journal_purpose_reference)\n VALUES(t.company_id,p_table,t.target_id,t.decision_id,t.target_hash,encode(sha256(convert_to(p_new::text,''UTF8'')),''hex''),t.journal_retain_until,t.journal_purpose_reference) ON CONFLICT DO NOTHING;\n SELECT x.* INTO STRICT o FROM gridex_ediel_retention.process_retention_origins x\n  WHERE x.company_id=t.company_id AND x.source_table=p_table AND x.target_id=t.target_id AND x.decision_id=t.decision_id;\n IF o.original_hash IS DISTINCT FROM t.target_hash\n  OR o.redacted_hash IS DISTINCT FROM encode(sha256(convert_to(p_new::text,''UTF8'')),''hex'')\n  OR o.journal_retain_until IS DISTINCT FROM t.journal_retain_until\n  OR o.journal_purpose_reference IS DISTINCT FROM t.journal_purpose_reference THEN\n  RAISE EXCEPTION ''record_retention_first_origin_binding_mismatch'' USING ERRCODE=''23514'';END IF;\n RETURN true;\nEND\n","body_md5":"ba1e28e057578a651fcc542a3af1087d","expected":{"owner":"gridex_ediel_retention_owner","proconfig":["search_path=pg_catalog"],"provolatile":"v","prosecdef":true,"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":0,"proargnames":["p_table","p_old","p_new"],"proargmodes":null,"return_type":"boolean","proretset":false,"identity_arguments":"p_table text, p_old jsonb, p_new jsonb","arguments":"p_table text, p_old jsonb, p_new jsonb","language":"plpgsql"}}'::jsonb;
 origin constant jsonb := '{"name":"gridex_ediel_retention.process_retention_origins","columns":[{"name":"id","type":"uuid","not_null":true,"generated":"","identity":"","default":"gen_random_uuid()"},{"name":"company_id","type":"uuid","not_null":true,"generated":"","identity":"","default":null},{"name":"source_table","type":"text","not_null":true,"generated":"","identity":"","default":null},{"name":"target_id","type":"uuid","not_null":true,"generated":"","identity":"","default":null},{"name":"decision_id","type":"uuid","not_null":true,"generated":"","identity":"","default":null},{"name":"original_hash","type":"text","not_null":true,"generated":"","identity":"","default":null},{"name":"redacted_hash","type":"text","not_null":true,"generated":"","identity":"","default":null},{"name":"journal_retain_until","type":"timestamp with time zone","not_null":true,"generated":"","identity":"","default":null},{"name":"journal_purpose_reference","type":"text","not_null":true,"generated":"","identity":"","default":null},{"name":"created_at","type":"timestamp with time zone","not_null":true,"generated":"","identity":"","default":"clock_timestamp()"}],"constraints":[{"name":"process_retention_origins_pkey","type":"p","definition":"PRIMARY KEY (id)","validated":true},{"name":"process_retention_origins_source_table_target_id_decision_i_key","type":"u","definition":"UNIQUE (source_table, target_id, decision_id)","validated":true},{"name":"process_retention_origins_decision_id_fkey","type":"f","definition":"FOREIGN KEY (decision_id) REFERENCES gridex_ediel_retention.record_decisions(id)","validated":true}],"triggers":[{"name":"immutable","enabled":"O","definition":"CREATE TRIGGER immutable BEFORE DELETE OR UPDATE ON gridex_ediel_retention.process_retention_origins FOR EACH ROW EXECUTE FUNCTION gridex_received_sources.reject_mutation()"},{"name":"no_truncate","enabled":"O","definition":"CREATE TRIGGER no_truncate BEFORE TRUNCATE ON gridex_ediel_retention.process_retention_origins FOR EAC