 origin_units constant jsonb := '[{"id":"canonical:2828","source":"supabase/schema.sql","byte_start":6705756,"byte_length":580,"sha256":"4bf7bbbf8d3b3584ffe18a851489e407fb3d385b1069f853f28c111391837e18","sql":"\n\n--\n-- Name: process_retention_origins; Type: TABLE; Schema: gridex_ediel_retention; Owner: -\n--\n\nCREATE TABLE gridex_ediel_retention.process_retention_origins (\n    id uuid DEFAULT gen_random_uuid() NOT NULL,\n    company_id uuid NOT NULL,\n    source_table text NOT NULL,\n    target_id uuid NOT NULL,\n    decision_id uuid NOT NULL,\n    original_hash text NOT NULL,\n    redacted_hash text NOT NULL,\n    journal_retain_until timestamp with time zone NOT NULL,\n    journal_purpose_reference text NOT NULL,\n    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL\n)"},{"id":"canonical:2829","source":"supabase/schema.sql","byte_start":6706337,"byte_length":92,"sha256":"86729c4fd08c01d4461a6aa6ceff3a11204acd9b6f1ab0b1e75a3b4fe5a02177","sql":"\n\nALTER TABLE ONLY gridex_ediel_retention.process_retention_origins FORCE ROW LEVEL SECURITY"},{"id":"canonical:4190","source":"supabase/schema.sql","byte_start":7846344,"byte_length":267,"sha256":"9a8f6cae8ad5858f9dc45a844259e77865681127f00b79d851db96877c7be541","sql":"\n\n--\n-- Name: process_retention_origins process_retention_origins_pkey; Type: CONSTRAINT; Schema: gridex_ediel_retention; Owner: -\n--\n\nALTER TABLE ONLY gridex_ediel_retention.process_retention_origins\n    ADD CONSTRAINT process_retention_origins_pkey PRIMARY KEY (id)"},{"id":"canonical:4191","source":"supabase/schema.sql","byte_start":7846612,"byte_length":362,"sha256":"19773f1cab81ccbe2fc651954ff7d7e8947a05a83539e98d0a50aa2efb4b0534","sql":"\n\n--\n-- Name: process_retention_origins process_retention_origins_source_table_target_id_decision_i_key; Type: CONSTRAINT; Schema: gridex_ediel_retention; Owner: -\n--\n\nALTER TABLE ONLY gridex_ediel_retention.process_retention_origins\n    ADD CONSTRAINT process_retention_origins_source_table_target_id_decision_i_key UNIQUE (source_table, target_id, decision_id)"},{"id":"canonical:7317","source":"supabase/schema.sql","byte_start":8660416,"byte_length":283,"sha256":"b0228411f4e21c0d48ea0b08db37c4561b3a34d2019e3add8cf06700799a4710","sql":"\n\n--\n-- Name: process_retention_origins immutable; Type: TRIGGER; Schema: gridex_ediel_retention; Owner: -\n--\n\nCREATE TRIGGER immutable BEFORE DELETE OR UPDATE ON gridex_ediel_retention.process_retention_origins FOR EACH ROW EXECUTE FUNCTION gridex_received_sources.reject_mutation()"},{"id":"canonical:7352","source":"supabase/schema.sql","byte_start":8670231,"byte_length":285,"sha256":"174542c1e3381658d8c6bc818fbc570e227ee83306fc4e26f3aaf4b0355374b4","sql":"\n\n--\n-- Name: process_retention_origins no_truncate; Type: TRIGGER; Schema: gridex_ediel_retention; Owner: -\n--\n\nCREATE TRIGGER no_truncate BEFORE TRUNCATE ON gridex_ediel_retention.process_retention_origins FOR EACH STATEMENT EXECUTE FUNCTION gridex_received_sources.reject_mutation()"},{"id":"canonical:8957","source":"supabase/schema.sql","byte_start":9166594,"byte_length":358,"sha256":"46e746891be1002fea68ca9ccdb237137c3c65262f4ee417eb246c1d1a869210","sql":"\n\n--\n-- Name: process_retention_origins process_retention_origins_decision_id_fkey; Type: FK CONSTRAINT; Schema: gridex_ediel_retention; Owner: -\n--\n\nALTER TABLE ONLY gridex_ediel_retention.process_retention_origins\n    ADD CONSTRAINT process_retention_origins_decision_id_fkey FOREIGN KEY (decision_id) REFERENCES gridex_ediel_retention.record_decisions(id)"},{"id":"canonical:10709","source":"supabase/schema.sql","byte_start":9728942,"byte_length":192,"sha256":"e6f4e27a2b7b351aaffa65d79671ca05779ab23828784a048e11adb96ee2442d","sql":"\n\n--\n-- Name: process_retention_origins; Type: ROW SECURITY; Schema: gridex_ediel_retention; Owner: -\n--\n\nALTER TABLE gridex_ediel_retention.process_retention_origins ENABLE ROW LEVEL SECURITY"}]'::jsonb;
 prerequisites constant jsonb := '[{"signature":"public.ediel_is_qualified_customer_record_transition_v1(text,jsonb,jsonb)","body_md5":"755aa9f0a18a020e34c333ad0b303f69"},{"signature":"public.ediel_is_qualified_finance_retention_transition_v1(text,text,jsonb,jsonb)","body_md5":"f940117012d77b8b6f22b19748ba5416"},{"signature":"gridex_ediel_retention.record_redacted_v1(text,jsonb)","body_md5":"b0d700d17357e2ba021a7a5209ed0612"},{"signature":"gridex_ediel_retention.finance_redacted_v1(text,jsonb,text)","body_md5":"8e2fe04f1f811b60111e42e50446fec5"},{"signature":"gridex_received_sources.reject_mutation()","body_md5":"f7e8de1214441a6e4396617536b37164"},{"signature":"public.gridex_company_retained_history_v1(uuid)","body_md5":"72b22a22ef2e5f0d2ce79e02075ccee6"}]'::jsonb;
 record_class constant jsonb := '{"retention_class":"contract_signature_personal_snapshot","source_table":"customer_contracts","permission_key":"ediel.retention.signature","operation":"redact_contract_signature_personal_snapshot","redaction":{"signature_snapshot":{},"signed_ip_hash":null,"signed_user_agent":null}}'::jsonb;
 finance_class constant jsonb := '{"retention_class":"settlement_calculation_body","source_schema":"public","source_table":"portfolio_monthly_settlements","id_column":"id","body_columns":["calculation_snapshot"],"permission_key":"ediel.retention.settlement_copy_evidence","source_kind":"settlement","operation":"redact_finance_copy_body"}'::jsonb;
 spec jsonb; required jsonb; actual jsonb; expected jsonb; target oid; capture_owner oid;
 unit jsonb; col jsonb;before_function pg_catalog.pg_proc%rowtype;after_function pg_catalog.pg_proc%rowtype;
 delegate pg_catalog.pg_proc%rowtype; before_delegate pg_catalog.pg_proc%rowtype; definition text; protected_customer_data jsonb;
BEGIN
 IF NOT EXISTS(SELECT FROM pg_catalog.pg_roles WHERE rolname='gridex_ediel_retention_owner'
  AND NOT rolcanlogin AND NOT rolsuper AND NOT rolinherit AND rolbypassrls) THEN
  RAISE EXCEPTION 'retention_audit_exact_source_internal_owner_required';END IF;
 FOR required IN SELECT value FROM jsonb_array_elements(prerequisites) LOOP
  IF coalesce((SELECT md5(prosrc) FROM pg_catalog.pg_proc WHERE oid=to_regprocedure(required->>'signature')),'absent')
   IS DISTINCT FROM required->>'body_md5' THEN
   RAISE EXCEPTION 'retention_audit_exact_source_prerequisite_required: %',required->>'signature';END IF;
 END LOOP;
 SELECT to_jsonb(k) INTO actual FROM gridex_ediel_retention.record_class_catalog k WHERE source_table='customer_contracts';
 IF actual IS DISTINCT FROM record_class THEN RAISE EXCEPTION 'retention_audit_record_class_source_mapping_changed';END IF;
 SELECT to_jsonb(k) INTO actual FROM gridex_ediel_retention.finance_class_catalog k WHERE source_schema='public' AND source_table='portfolio_monthly_settlements';
 IF actual IS DISTINCT FROM finance_class THEN RAISE EXCEPTION 'retention_audit_finance_class_source_mapping_changed';END IF;
 SELECT to_jsonb(p) INTO protected_customer_data FROM pg_catalog.pg_proc p WHERE p.oid=to_regprocedure('public.gridex_company_has_customer_data(uuid)');
 SELECT proowner INTO STRICT capture_owner FROM pg_catalog.pg_proc WHERE oid=to_regprocedure('gridex_correction_process.capture_v1()');
 IF to_regclass(origin->>'name') IS NULL THEN
  FOR unit IN SELECT value FROM jsonb_array_elements(origin_units) LOOP EXECUTE unit->>'sql';END LOOP;
  ALTER TABLE gridex_ediel_retention.process_retention_origins OWNER TO gridex_ediel_retention_owner;
  REVOKE ALL ON TABLE gridex_ediel_retention.process_retention_origins FROM PUBLIC,anon,authenticated,service_role;
 END IF;
 target:=to_regclass(origin->>'name');
 SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',a.atttypid::regtype::text,
  'not_null',a.attnotnull,'generated',a.attgenerated,'identity',a.attidentity,
  'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) INTO actual
 FROM pg_catalog.pg_attribute a LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
 WHERE a.attrelid=target AND a.attnum>0 AND NOT a.attisdropped;
 IF actual IS DISTINCT FROM origin->'columns' THEN RAISE EXCEPTION 'retention_audit_origin_columns_changed';END IF;
 SELECT jsonb_agg(jsonb_build_object('name',c.conname,'type',c.contype,'definition',pg_get_constraintdef(c.oid,true),'validated',c.convalidated) ORDER BY c.conname)
 INTO actual FROM pg_catalog.pg_constraint c WHERE c.conrelid=target;
 SELECT jsonb_agg(value ORDER BY value->>'name') INTO expected FROM jsonb_array_elements(origin->'constraints');
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'retention_audit_origin_constraints_changed';END IF;
 SELECT jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid)) ORDER BY t.tgname)
 INTO actual FROM pg_catalog.pg_trigger t WHERE t.tgrelid=target AND NOT t.tgisinternal;
 SELECT jsonb_agg(value ORDER BY value->>'name') INTO expected FROM jsonb_array_elements(origin->'triggers');
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'retention_audit_origin_immutable_trigger_changed';END IF;
 IF NOT EXISTS(SELECT FROM pg_catalog.pg_class c JOIN pg_catalog.pg_roles r ON r.oid=c.relowner
  WHERE c.oid=target AND r.rolname='gridex_ediel_retention_owner' AND c.relrowsecurity AND c.relforcerowsecurity
  AND NOT EXISTS(SELECT FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) WHERE grantee<>c.relowner))
  OR EXISTS(SELECT FROM pg_catalog.pg_policy WHERE polrelid=target) THEN
  RAISE EXCEPTION 'retention_audit_origin_exact_owner_only_force_rls_required';END IF;
 SELECT * INTO delegate FROM pg_catalog.pg_proc WHERE oid=to_regprocedure(helper->>'signature');
 IF NOT FOUND THEN
  EXECUTE helper->>'definition';
  ALTER FUNCTION public.ediel_capture_customer_record_retention_origin_v1(text,jsonb,jsonb) OWNER TO gridex_ediel_retention_owner;
  REVOKE ALL ON FUNCTION public.ediel_capture_customer_record_retention_origin_v1(text,jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;
  EXECUTE format('GRANT EXECUTE ON FUNCTION public.ediel_capture_customer_record_retention_origin_v1(text,jsonb,jsonb) TO %I',pg_get_userbyid(capture_owner));
  SELECT * INTO STRICT delegate FROM pg_catalog.pg_proc WHERE oid=to_regprocedure(helper->>'signature');
 END IF;
 SELECT jsonb_build_object('owner',pg_get_userbyid(p.proowner),'proconfig',p.proconfig,
  'provolatile',p.provolatile,'prosecdef',p.prosecdef,'proisstrict',p.proisstrict,
  'proleakproof',p.proleakproof,'proparallel',p.proparallel,'procost',p.procost,'prorows',p.prorows,
  'proargnames',p.proargnames,'proargmodes',p.proargmodes::text,'return_type',p.prorettype::regtype::text,
  'proretset',p.proretset,'identity_arguments',pg_get_function_identity_arguments(p.oid),
  'arguments',pg_get_function_arguments(p.oid),'language',l.lanname)
 INTO actual FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_language l ON l.oid=p.prolang WHERE p.oid=delegate.oid;
 IF actual IS DISTINCT FROM helper->'expected'
  OR EXISTS(SELECT FROM aclexplode(coalesce(delegate.proacl,acldefault('f',delegate.proowner)))
   WHERE grantee NOT IN(delegate.proowner,capture_owner) OR privilege_type<>'EXECUTE' OR is_grantable)
  OR NOT has_function_privilege(capture_owner,delegate.oid,'EXECUTE') THEN
  RAISE EXCEPTION 'retention_audit_internal_helper_full_abi_or_acl_changed';END IF;
 IF md5(delegate.prosrc) IS DISTINCT FROM helper->>'body_md5' THEN
  IF md5(delegate.prosrc) IS DISTINCT FROM helper->>'source_before_body_md5'
   OR delegate.prosrc IS DISTINCT FROM helper->>'original' THEN
   RAISE EXCEPTION 'retention_audit_internal_helper_unknown_body';END IF;
  before_delegate:=delegate;definition:=pg_get_functiondef(delegate.oid);
  IF strpos(definition,helper->>'original')=0 THEN RAISE EXCEPTION 'retention_audit_exact_original_helper_body_required';END IF;
  EXECUTE replace(definition,helper->>'original',helper->>'patched');
  SELECT * INTO STRICT delegate FROM pg_catalog.pg_proc WHERE oid=to_regprocedure(helper->>'signature');
  IF (to_jsonb(delegate)-'prosrc')IS DISTINCT FROM(to_jsonb(before_delegate)-'prosrc')
   OR md5(delegate.prosrc)IS DISTINCT FROM helper->>'body_md5' THEN
   RAISE EXCEPTION 'retention_audit_all_existing_helper_identity_attributes_must_remain_exact';END IF;
 END IF;
 FOR spec IN SELECT value FROM jsonb_array_elements(config) LOOP
  SELECT * INTO before_function FROM pg_catalog.pg_proc WHERE oid=to_regprocedure(spec->>'signature');
  IF NOT FOUND THEN RAISE EXCEPTION 'retention_audit_existing_target_required: %',spec->>'signature';END IF;
  SELECT jsonb_build_object('owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,
   'proconfig',p.proconfig,'provolatile',p.provolatile,'prosecdef',p.prosecdef,
   'proisstrict',p.proisstrict,'proleakproof',p.proleakproof,'proparallel',p.proparallel,
   'procost',p.procost,'prorows',p.prorows,'proargnames',p.proargnames,'proargmodes',p.proargmodes::text,
   'return_type',p.prorettype::regtype::text,'proretset',p.proretset,
   'identity_arguments',pg_get_function_identity_arguments(p.oid),
   'arguments',pg_get_function_arguments(p.oid),'language',l.lanname)
  INTO actual FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_language l ON l.oid=p.prolang WHERE p.oid=before_function.oid;
  IF actual IS DISTINCT FROM spec->'expected' THEN
   RAISE EXCEPTION 'retention_audit_target_attributes_changed_requires_review: %',spec->>'signature';END IF;
  IF md5(before_function.prosrc)=spec->>'after' THEN CONTINUE;END IF;
  IF md5(before_function.prosrc) IS DISTINCT FROM spec->>'before'
   OR before_function.prosrc IS DISTINCT FROM spec->>'original' THEN
   RAISE EXCEPTION 'retention_audit_target_body_changed_requires_review: %',spec->>'signature';END IF;
  definition:=pg_get_functiondef(before_function.oid);
  IF strpos(definition,spec->>'original')=0 THEN RAISE EXCEPTION 'retention_audit_exact_original_body_required';END IF;
  EXECUTE replace(definition,spec->>'original',spec->>'patched');
  SELECT * INTO STRICT after_function FROM pg_catalog.pg_proc WHERE oid=to_regprocedure(spec->>'signature');
  IF (to_jsonb(after_function)-'prosrc') IS DISTINCT FROM(to_jsonb(before_function)-'prosrc')
   OR md5(after_function.prosrc) IS DISTINCT FROM spec->>'after' THEN
   RAISE EXCEPTION 'retention_audit_all_target_identity_attributes_must_remain_exact: %',spec->>'signature';END IF;
 END LOOP;
 IF protected_customer_data IS DISTINCT FROM(SELECT to_jsonb(p) FROM pg_catalog.pg_proc p WHERE p.oid=to_regprocedure('public.gridex_company_has_customer_data(uuid)')) THEN
  RAISE EXCEPTION 'retention_audit_stronger_customer_data_helper_must_remain_unchanged';END IF;
END
$retention_audit_harddelete$;
NOTIFY pgrst,'reload schema';
COMMIT;
